css:
.wrap { width:100%; height:100%; display:flex; align-items:center; justify-content:center;
        flex-direction:column; gap:28px; font-family:"Noto Sans"; background:#0d1117; }
.pill { padding:14px 30px; border-radius:999px; background:#f4f6fb; color:#0d1117;
        font-size:22px; font-weight:700; letter-spacing:1px;
        animation: pop 0.8s cubic-bezier(.2,.9,.3,1.4) both; }
.dot  { width:22px; height:22px; border-radius:50%; background:#d9642a;
        animation: bounce 1.2s ease-in-out infinite; }
@keyframes pop    { from { opacity:0; transform:scale(0.6); } to { opacity:1; transform:scale(1); } }
@keyframes bounce { 0%,100% { transform:translateY(0); } 50% { transform:translateY(-30px); } }
